'use client';

import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import rehypeHighlight from 'rehype-highlight';
import rehypeRaw from 'rehype-raw';
import 'highlight.js/styles/github-dark.css';

interface MarkdownPreviewProps {
  content: string;
  className?: string;
}

export default function MarkdownPreview({
  content,
  className = ''
}: MarkdownPreviewProps) {
  return (
    <div className={`markdown-preview prose prose-sm max-w-none ${className}`}>
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        rehypePlugins={[rehypeHighlight, rehypeRaw]}
        components={{
          code: ({ node, inline, className, children, ...props }: any) => {
            const match = /language-(\w+)/.exec(className || '');
            return !inline ? (
              <code className={className} {...props}>
                {children}
              </code>
            ) : (
              <code
                className="bg-gray-100 text-red-600 px-1.5 py-0.5 rounded text-sm font-mono"
                {...props}
              >
                {children}
              </code>
            );
          },
          a: ({ node, children, href, ...props }: any) => (
            <a
              href={href}
              target="_blank"
              rel="noopener noreferrer"
              className="text-amber-600 hover:text-amber-700 underline"
              {...props}
            >
              {children}
            </a>
          ),
          blockquote: ({ node, children, ...props }: any) => (
            <blockquote
              className="border-l-4 border-amber-300 pl-4 py-1 my-4 bg-amber-50/50 italic text-gray-700"
              {...props}
            >
              {children}
            </blockquote>
          ),
          table: ({ node, children, ...props }: any) => (
            <div className="overflow-x-auto my-4">
              <table
                className="min-w-full divide-y divide-gray-200 border border-gray-200"
                {...props}
              >
                {children}
              </table>
            </div>
          ),
          th: ({ node, children, ...props }: any) => (
            <th
              className="px-4 py-2 bg-gray-50 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
              {...props}
            >
              {children}
            </th>
          ),
          td: ({ node, children, ...props }: any) => (
            <td
              className="px-4 py-2 text-sm text-gray-700 border-t border-gray-200"
              {...props}
            >
              {children}
            </td>
          ),
        }}
      >
        {content}
      </ReactMarkdown>
      <style jsx global>{`
        .markdown-preview pre {
          background-color: #1e293b;
          border-radius: 0.5rem;
          padding: 1rem;
          overflow-x: auto;
          margin: 1rem 0;
        }
        .markdown-preview pre code {
          color: #e2e8f0;
          font-size: 0.875rem;
        }
        .markdown-preview h1,
        .markdown-preview h2,
        .markdown-preview h3,
        .markdown-preview h4,
        .markdown-preview h5,
        .markdown-preview h6 {
          font-weight: 600;
          color: #111827;
          margin-top: 1.5rem;
          margin-bottom: 0.75rem;
        }
        .markdown-preview h1 {
          font-size: 1.875rem;
          border-bottom: 2px solid #e5e7eb;
          padding-bottom: 0.5rem;
        }
        .markdown-preview h2 {
          font-size: 1.5rem;
          border-bottom: 1px solid #e5e7eb;
          padding-bottom: 0.25rem;
        }
        .markdown-preview h3 {
          font-size: 1.25rem;
        }
        .markdown-preview p {
          margin: 0.75rem 0;
          line-height: 1.75;
          color: #374151;
        }
        .markdown-preview ul,
        .markdown-preview ol {
          margin: 0.75rem 0;
          padding-left: 1.5rem;
        }
        .markdown-preview ul {
          list-style-type: disc;
        }
        .markdown-preview ol {
          list-style-type: decimal;
        }
        .markdown-preview li {
          margin: 0.25rem 0;
          color: #374151;
        }
        .markdown-preview img {
          max-width: 100%;
          height: auto;
          border-radius: 0.5rem;
          margin: 1rem 0;
        }
        .markdown-preview hr {
          border-color: #e5e7eb;
          margin: 2rem 0;
        }
      `}</style>
    </div>
  );
}

