'use client';

interface MarkdownPreviewProps {
  content: string;
  className?: string;
}

export default function MarkdownPreview({
  content,
  className = ''
}: MarkdownPreviewProps) {
  return (
    <>
      <div
        className={`markdown-preview prose prose-sm max-w-none ${className}`}
        dangerouslySetInnerHTML={{ __html: content }}
      />
      <style jsx global>{`
        .markdown-preview h1 {
          font-size: 1.5rem;
          font-weight: 700;
          margin: 1rem 0 0.5rem;
          line-height: 1.2;
          color: #111827;
        }
        .markdown-preview h2 {
          font-size: 1.25rem;
          font-weight: 600;
          margin: 0.875rem 0 0.5rem;
          line-height: 1.3;
          color: #111827;
        }
        .markdown-preview h3 {
          font-size: 1.125rem;
          font-weight: 600;
          margin: 0.75rem 0 0.5rem;
          line-height: 1.4;
          color: #111827;
        }
        .markdown-preview p {
          margin: 0.5rem 0;
          line-height: 1.6;
          color: #374151;
        }
        .markdown-preview ul,
        .markdown-preview ol {
          padding-left: 1.5rem;
          margin: 0.5rem 0;
        }
        .markdown-preview li {
          margin: 0.25rem 0;
          color: #374151;
        }
        .markdown-preview blockquote {
          border-left: 4px solid #fbbf24;
          padding-left: 1rem;
          margin: 1rem 0;
          background-color: #fffbeb;
          color: #6b7280;
        }
        .markdown-preview code {
          background-color: #f3f4f6;
          color: #ef4444;
          padding: 0.2em 0.4em;
          border-radius: 3px;
          font-size: 0.875em;
        }
        .markdown-preview pre {
          background-color: #1e293b;
          color: #e2e8f0;
          padding: 1rem;
          border-radius: 0.5rem;
          overflow-x: auto;
          margin: 1rem 0;
        }
        .markdown-preview pre code {
          background-color: transparent;
          color: inherit;
          padding: 0;
        }
        .markdown-preview img {
          max-width: 100%;
          height: auto;
          border-radius: 0.5rem;
          margin: 1rem 0;
        }
        .markdown-preview a {
          color: #d97706;
          text-decoration: underline;
        }
        .markdown-preview strong {
          font-weight: 700;
        }
        .markdown-preview em {
          font-style: italic;
        }
        .markdown-preview s {
          text-decoration: line-through;
        }
        .markdown-preview u {
          text-decoration: underline;
        }
      `}</style>
    </>
  );
}

