{"toolName":"Write","toolInput":{"file_path":"/Users/wanghu/work/study/niubi/goodable/data/projects/p-36cde1kh/components/MarkdownEditor.tsx","content":"'use client';

import { useEffect, useRef, useState } from 'react';
import Vditor from 'vditor';
import 'vditor/dist/index.css';

interface MarkdownEditorProps {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
}

export default function MarkdownEditor({
  value,
  onChange,
  placeholder = 'Start writing...'
}: MarkdownEditorProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const vditorRef = useRef<Vditor>();
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    if (!containerRef.current) return;

    const vditor = new Vditor(containerRef.current, {
      height: 400,
      mode: 'wysiwyg', // 所见即所得模式
      placeholder,
      value,
      cache: {
        enable: false,
      },
      after: () => {
        vditorRef.current = vditor;
        setIsReady(true);
      },
      input: (value) => {
        onChange(value);
      },
      toolbar: [
        'headings',
        'bold',
        'italic',
        'strike',
        '|',
        'list',
        'ordered-list',
        'check',
        '|',
        'quote',
        'code',
        'inline-code',
        '|',
        'link',
        'upload',
        'table',
        '|',
        'undo',
        'redo',
        '|',
        'preview',
        'fullscreen',
      ],
      theme: 'light',
      preview: {
        theme: {
          current: 'light',
        },
      },
    });

    return () => {
      if (vditorRef.current) {
        vditorRef.current.destroy();
        vditorRef.current = undefined;
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (isReady && vditorRef.current && value !== vditorRef.current.getValue()) {
      vditorRef.current.setValue(value);
    }
  }, [value, isReady]);

  return <div ref={containerRef} className="vditor-container" />;
}
"},"filePath":"/Users/wanghu/work/study/niubi/goodable/data/projects/p-36cde1kh/components/MarkdownEditor.tsx","action":"Created","requestId":"05c72f8f-b4ad-426c-ac4c-18fcbd2ba74b"}

