'use client';

import { useEffect, useRef, useState } from 'react';
import Vditor from 'vditor';
import 'vditor/dist/index.css';

interface MarkdownEditorProps {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
}

export default function MarkdownEditor({
  value,
  onChange,
  placeholder = 'Start writing...'
}: MarkdownEditorProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const vditorRef = useRef<Vditor>();
  const [isReady, setIsReady] = useState(false);
  const initTimeoutRef = useRef<NodeJS.Timeout>();

  useEffect(() => {
    if (!containerRef.current) return;

    // 添加超时保护，如果10秒后还没初始化完成，强制显示编辑器区域
    initTimeoutRef.current = setTimeout(() => {
      if (!isReady) {
        console.warn('Vditor initialization timeout, showing editor anyway');
        setIsReady(true);
      }
    }, 10000);

    const vditor = new Vditor(containerRef.current, {
      height: 400,
      mode: 'wysiwyg',
      placeholder,
      value,
      cache: {
        enable: false,
      },
      init: () => {
        if (initTimeoutRef.current) {
          clearTimeout(initTimeoutRef.current);
        }
        vditorRef.current = vditor;
        setIsReady(true);
      },
      input: (value) => {
        onChange(value);
      },
      toolbar: [
        'headings',
        'bold',
        'italic',
        'strike',
        '|',
        'list',
        'ordered-list',
        'check',
        '|',
        'quote',
        'code',
        'inline-code',
        '|',
        'link',
        'table',
        '|',
        'undo',
        'redo',
        '|',
        'preview',
        'fullscreen',
      ],
    });

    return () => {
      if (initTimeoutRef.current) {
        clearTimeout(initTimeoutRef.current);
      }
      try {
        if (vditor) {
          vditor.destroy();
        }
      } catch (e) {
        console.error('Error destroying Vditor:', e);
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (isReady && vditorRef.current) {
      try {
        const currentValue = vditorRef.current.getValue();
        if (value !== currentValue) {
          vditorRef.current.setValue(value);
        }
      } catch (e) {
        console.error('Error setting Vditor value:', e);
      }
    }
  }, [value, isReady]);

  if (!isReady) {
    return (
      <div className="w-full h-96 border border-gray-200 rounded-lg p-4 bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-500 mx-auto mb-2"></div>
          <p className="text-sm text-gray-500">加载编辑器...</p>
        </div>
      </div>
    );
  }

  return <div ref={containerRef} className="vditor-container" />;
}

