  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
}

export default function MarkdownEditor({
  value,
  onChange,
  placeholder = 'Start writing...'
}: MarkdownEditorProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const vditorRef = useRef<Vditor>();
  const [isReady, setIsReady] = useState(false);
  const [initCalled, setInitCalled] = useState(false);

  useLayoutEffect(() => {
    if (!containerRef.current || initCalled) return;

    console.log('Starting Vditor initialization...');
    setInitCalled(true);

    const vditor = new Vditor(containerRef.current, {
      height: 400,
      mode: 'wysiwyg',
      placeholder,
      value,
      cache: {
        enable: false,
      },
      init: () => {
        console.log('Vditor initialized successfully');
        vditorRef.current = vditor;
        setIsReady(true);
      },
      input: (value) => {
        onChange(value);
      },
      toolbar: [
        'headings',
        'bold',
        'italic',
        'strike',
        '|',
        'list',
        'ordered-list',
        'check',
        '|',
        'quote',
        'code',
        'inline-code',
        '|',
        'link',
        'table',
        '|',
        'undo',
        'redo',
        '|',
        'preview',
        'fullscreen',
      ],
    });

    // 备用方案：3秒后强制显示
    const fallbackTimer = setTimeout(() => {
      if (!isReady) {
        console.warn('Vditor fallback: forcing ready state');
        vditorRef.current = vditor;
        setIsReady(true);
      }
