'use client';

import { useEffect, useRef, useState } from 'react';
import Vditor from 'vditor';
import 'vditor/dist/index.css';

interface MarkdownEditorProps {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
}

export default function MarkdownEditor({
  value,
  onChange,
  placeholder = 'Start writing...'
}: MarkdownEditorProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const vditorRef = useRef<Vditor>();
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    if (!containerRef.current) return;

    console.log('Container element:', containerRef.current);
    console.log('Starting Vditor init...');

    try {
      const vditor = new Vditor(containerRef.current, {
        height: 400,
        mode: 'wysiwyg',
        placeholder,
        value,
        cache: {
          enable: false,
        },
        // 使用多个回调确保至少一个被触发
        init: () => {
          console.log('Vditor init callback triggered');
          vditorRef.current = vditor;
          setIsReady(true);
        },
        after: () => {
          console.log('Vditor after callback triggered');
          vditorRef.current = vditor;
          setIsReady(true);
        },
        input: (value) => {
          onChange(value);
        },
        toolbar: [
          'headings',
          'bold',
          'italic',
          'strike',
          '|',
          'list',
          'ordered-list',
          'check',
          '|',
          'quote',
          'code',
          'inline-code',
          '|',
          'link',
          'table',
          '|',
          'undo',
          'redo',
          '|',
          'preview',
          'fullscreen',
        ],
      });

      console.log('Vditor instance created:', vditor);

      // 如果2秒后还没有ready，强制设置为ready
      const forceReadyTimer = setTimeout(() => {
        if (!isReady) {
          console.warn('Forcing Vditor to ready state');
          console.log('Vditor element:', containerRef.current);
          vditorRef.current = vditor;
          setIsReady(true);
        }
      }, 2000);

      return () => {
        clearTimeout(forceReadyTimer);
        try {
          if (vditor) {
            vditor.destroy();
          }
        } catch (e) {
          console.error('Error destroying Vditor:', e);
        }
      };
    } catch (error) {
      console.error('Error creating Vditor:', error);
      setIsReady(true); // 即使出错也显示编辑器区域
    }
  }, []);

  useEffect(() => {
    if (isReady && vditorRef.current) {
      try {
        const currentValue = vditorRef.current.getValue();
        if (value !== currentValue) {
          vditorRef.current.setValue(value);
        }
      } catch (e) {
        console.error('Error setting Vditor value:', e);
      }
    }
  }, [value, isReady]);

  if (!isReady) {
    return (
      <div className="w-full h-96 border border-gray-200 rounded-lg p-4 bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-500 mx-auto mb-2"></div>
          <p className="text-sm text-gray-500">加载编辑器...</p>
        </div>
      </div>
    );
  }

  return <div ref={containerRef} className="vditor-container" />;
}

