'use client';

import { useEffect, useRef, useState } from 'react';
import Vditor from 'vditor';
import 'vditor/dist/index.css';

interface MarkdownEditorProps {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
}

export default function MarkdownEditor({
  value,
  onChange,
  placeholder = 'Start writing...'
}: MarkdownEditorProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const vditorRef = useRef<Vditor>();
  const [isReady, setIsReady] = useState(false);
  const [mounted, setMounted] = useState(false);

  // 组件挂载标记
  useEffect(() => {
    console.log('MarkdownEditor component mounted');
    setMounted(true);
  }, []);

  useEffect(() => {
    if (!mounted || !containerRef.current) {
      console.log('Waiting for mount and container...', { mounted, hasContainer: !!containerRef.current });
      return;
    }

    console.log('Container element:', containerRef.current);
    console.log('Starting Vditor init...');

    const initVditor = () => {
      try {
        const vditor = new Vditor(containerRef.current!, {
          height: 400,
          mode: 'wysiwyg',
          placeholder,
          value,
          cache: {
            enable: false,
          },
          init: () => {
            console.log('Vditor init callback triggered');
            vditorRef.current = vditor;
            setIsReady(true);
          },
          after: () => {
            console.log('Vditor after callback triggered');
            vditorRef.current = vditor;
            setIsReady(true);
          },
          input: (value) => {
            onChange(value);
          },
          toolbar: [
            'headings',
            'bold',
            'italic',
            'strike',
            '|',
            'list',
            'ordered-list',
            'check',
            '|',
            'quote',
            'code',
            'inline-code',
            '|',
            'link',
            'table',
            '|',
            'undo',
            'redo',
            '|',
            'preview',
            'fullscreen',
          ],
        });

        console.log('Vditor instance created:', vditor);

        // 备用方案：1.5秒后强制显示
        const forceReadyTimer = setTimeout(() => {
          if (!isReady) {
            console.warn('Forcing Vditor to ready state after timeout');
            vditorRef.current = vditor;
            setIsReady(true);
          }
        }, 1500);

        return () => {
          clearTimeout(forceReadyTimer);
          try {
            if (vditor) {
              vditor.destroy();
            }
          } catch (e) {
            console.error('Error destroying Vditor:', e);
          }
        };
      } catch (error) {
        console.error('Error creating Vditor:', error);
        setIsReady(true);
      }
    };

    // 延迟一点执行，确保 DOM 完全准备好
    const timer = setTimeout(initVditor, 100);

    return () => {
      clearTimeout(timer);
    };
  }, [mounted]);

  useEffect(() => {
    if (isReady && vditorRef.current) {
      try {
        const currentValue = vditorRef.current.getValue();
        if (value !== currentValue) {
          vditorRef.current.setValue(value);
        }
      } catch (e) {
        console.error('Error setting Vditor value:', e);
      }
    }
  }, [value, isReady]);

  console.log('MarkdownEditor render, isReady:', isReady);

