'use client';

import { useEffect, useRef, useState } from 'react';
import Vditor from 'vditor';
import 'vditor/dist/index.css';

interface MarkdownEditorProps {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
}

export default function MarkdownEditor({
  value,
  onChange,
  placeholder = 'Start writing...'
}: MarkdownEditorProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const vditorRef = useRef<Vditor>();
  const [isReady, setIsReady] = useState(false);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    if (!mounted || !containerRef.current) {
      return;
    }

    const initVditor = () => {
      try {
        const vditor = new Vditor(containerRef.current!, {
          height: 400,
          mode: 'sv', // 分屏预览模式：左边编辑，右边预览
          placeholder,
          value,
          cache: {
            enable: false,
          },
          init: () => {
            vditorRef.current = vditor;
            setIsReady(true);
          },
          after: () => {
            vditorRef.current = vditor;
            setIsReady(true);
          },
          input: (value) => {
            onChange(value);
          },
          toolbar: [
            'headings',
            'bold',
            'italic',
            'strike',
            '|',
            'list',
            'ordered-list',
            'check',
            '|',
            'quote',
            'code',
            'inline-code',
            '|',
            'link',
            'table',
            '|',
            'undo',
            'redo',
            '|',
            'preview',
            'fullscreen',
          ],
        });

        // 备用方案：1.5秒后强制显示
        const forceReadyTimer = setTimeout(() => {
          if (!isReady) {
            vditorRef.current = vditor;
            setIsReady(true);
          }
        }, 1500);

        return () => {
          clearTimeout(forceReadyTimer);
          try {
            if (vditor) {
              vditor.destroy();
            }
          } catch (e) {
            console.error('Error destroying Vditor:', e);
          }
        };
      } catch (error) {
        console.error('Error creating Vditor:', error);
        setIsReady(true);
      }
    };

    const timer = setTimeout(initVditor, 100);

    return () => {
      clearTimeout(timer);
    };
  }, [mounted]);

  useEffect(() => {
    // 只在编辑器完全初始化后才尝试设置值
    if (isReady && vditorRef.current && value) {
      try {
        const editor = vditorRef.current;
        if (editor && editor.vditor) {
          editor.setValue(value);
        }
      } catch (e) {
        console.error('Error setting Vditor value:', e);
      }
    }
  }, [value, isReady]);

  return (
    <div className="relative">
      {!isReady && (
        <div className="w-full h-96 border border-gray-200 rounded-lg p-4 bg-gray-50 flex items-center justify-center absolute inset-0 z-10">
          <div className="text-center">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-500 mx-auto mb-2"></div>
            <p className="text-sm text-gray-500">加载编辑器...</p>
          </div>
        </div>
      )}
      <div ref={containerRef} className="vditor-container" />
    </div>
  );
}

