'use client';

import { useState, useEffect } from 'react';
import MDEditor from '@uiw/react-md-editor';
import '@uiw/react-md-editor/markdown-editor.css';

interface MarkdownEditorProps {
  value: string;
  onChange: (value: string | undefined) => void;
  placeholder?: string;
}

export default function MarkdownEditor({
  value,
  onChange,
  placeholder = 'Start writing...'
}: MarkdownEditorProps) {
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted) {
    return (
      <div className="w-full h-96 border border-gray-200 rounded-lg p-4 bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-500 mx-auto mb-2"></div>
          <p className="text-sm text-gray-500">加载编辑器...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="markdown-editor-container" data-color-mode="light">
      <MDEditor
        value={value}
        onChange={onChange}
        placeholder={placeholder}
        height={400}
        preview="live"
        hideToolbar={false}
        visibleDragBar={false}
        textareaProps={{
          placeholder,
        }}
      />
      <style jsx global>{`
        .w-md-editor {
          background-color: white;
        }
        .w-md-editor-toolbar {
          background-color: #f9fafb;
          border-bottom: 1px solid #e5e7eb;
        }
        .w-md-editor-toolbar button {
          color: #6b7280;
        }
        .w-md-editor-toolbar button:hover {
          background-color: #f3f4f6;
          color: #374151;
        }
        .w-md-editor-toolbar button.active {
          background-color: #fef3c7;
          color: #d97706;
        }
        .w-md-editor-text-pre,
        .w-md-editor-text-input {
          font-size: 14px;
          line-height: 1.6;
        }
        .w-md-editor-text-pre > code,
        .w-md-editor-text-input > textarea {
          font-size: 14px;
          line-height: 1.6;
        }
        .wmde-markdown {
          background-color: transparent !important;
        }
        .wmde-markdown h1,
        .wmde-markdown h2,
        .wmde-markdown h3,
        .wmde-markdown h4,
        .wmde-markdown h5,
        .wmde-markdown h6 {
          color: #111827;
          border-bottom: 1px solid #e5e7eb;
          padding-bottom: 0.3em;
        }
        .wmde-markdown code {
          background-color: #f3f4f6;
          color: #ef4444;
          padding: 0.2em 0.4em;
          border-radius: 3px;
          font-size: 85%;
        }
        .wmde-markdown pre {
          background-color: #1e293b;
          border-radius: 0.5rem;
          padding: 1rem;
        }
        .wmde-markdown pre code {
          background-color: transparent;
          color: #e2e8f0;
          padding: 0;
        }
        .wmde-markdown blockquote {
          border-left: 4px solid #fbbf24;
          padding-left: 1rem;
          color: #6b7280;
          background-color: #fffbeb;
        }
        .wmde-markdown a {
          color: #d97706;
          text-decoration: none;
        }
        .wmde-markdown a:hover {
          text-decoration: underline;
        }
        .wmde-markdown table {
          border-collapse: collapse;
          width: 100%;
        }
        .wmde-markdown table th,
        .wmde-markdown table td {
          border: 1px solid #e5e7eb;
          padding: 0.5rem;
        }
        .wmde-markdown table th {
          background-color: #f9fafb;
        }
      `}</style>
    </div>
  );
}

